      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name IN ('RouteController.queryById','RouteRepository.findById','SELECT ts.route_stations','SELECT ts.route_distances','RouteController.queryAll','RouteController.queryByIds') GROUP BY ALL ORDER BY 1", "claim": "RouteController.queryById p95 is about 3174 ms while its DB children (findById, SQL) stay around 2-3 ms; queryAll and queryByIds stay fast."},
        {"kind": "trace", "sql": "SELECT p.span_name pname, c.span_name cname, c.attr_span_kind ck, count(*) n, approx_quantile(p.duration/1e6,0.5) p_ms, approx_quantile(c.duration/1e6,0.5) c_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-route-service' AND p.span_name='RouteController.queryById' GROUP BY ALL", "claim": "Inside queryById about 3170 ms of self time is unaccounted for by child DB spans of about 0.3-2 ms."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE service_name='ts-route-service' AND metric IN ('k8s.pod.cpu_limit_utilization','container.memory.working_set','jvm.cpu.recent_utilization') GROUP BY metric", "claim": "Route-service CPU and memory stay at or below normal levels, so the slowness is not resource saturation."}
